const uno = part("uno","arduino-uno",{"at":[-37,0]})
const board = part("board","breadboard-half",{"at":[-5,0]})
const motor = part("motor","dc-motor",{"at":[34,7]})
const battery = part("battery","battery-9v",{"at":[4,23],"rotate":270})
const q = part("q","npn-transistor",{})
seat("q","board","B","G16")
const r = part("r","resistor",{})
seat("r","board","2","G16")
const diode = part("diode","rectifier-diode",{})
seat("diode","board","A","G17")
rail("supply","board","+bottom","battery.+",["motor.1","diode.C"])
rail("return","board","-bottom","battery.-",["q.E","uno.GND.2"])
wire("motor-switch","motor.2","board:G17","ground")
wire("drive","uno.9","board:G10","signal")

